      top: 50%;
      transform: translateY(-50%);
      right: 10px;
    }
  </style>
</head>
<body>
  <!-- Contenedor para el botón de abrir el modal -->
  <button id="open-modal">Abrir modal</button>

  <!-- Modal para el chatbot falso -->
  <div id="modal" class="modal">
    <!-- Contenedor para el contenido del modal -->
    <div class="modal-content">
      <span class="close">&times;</span>
      <h2>Chatbot False</h2>
      <div class="chat-history">
        <div class="chat-message user">
          <p>Usuario: Hola, ¿cómo estás?</p>
        </div>
        <div class="chat-message bot">
          <p>Chatbot: ¡Hola! Estoy bien, gracias. ¿Y tú cómo estás?</p>
        </div>
        <div class="chat-message user">
          <p>Usuario: Estoy bien, gracias. ¿Qué puedes hacer?</p>
        </div>
        <div class="chat-message bot">
          <p>Chatbot: Soy una IA capaz de responder a tus preguntas y ayudarte en diferentes temas. ¿En qué puedo ayudarte hoy?</p>
        </div>
      </div>
      <!-- Input para escribir mensajes y botón de enviar -->
      <form id="chat-form">
        <input type="text" id="message-input" placeholder="Escribe un mensaje...">
        <button type="submit">Enviar</button>
      </form>
    </div>
  </div>

  <!-- Script para abrir y cerrar el modal -->
  <script>
    var modal = document.getElementById("modal");
    var btn = document.getElementById("open-modal");
    var close = document.getElementsByClassName("close")[0];

    btn.onclick = function() {
      modal.style.display = "block";
    }

    close.onclick = function() {
      modal.style.display = "none";
