#include <iostream>
#include <fstream>
#include <string>
#include <algorithm>

int main() {
    std::string word; // Palabra a buscar
    std::string line; // Línea leída del archivo
    int count = 0; // Contador de apariciones

    // Solicitamos la palabra a buscar al usuario
    std::cout << "Introduzca la palabra a buscar: ";
    std::getline(std::cin, word);

    // Abrimos el archivo para leerlo línea por línea
    std::ifstream file("archivo.txt");

    if (!file) {
        std::cerr << "Error al abrir el archivo." << std::endl;
        return 1;
    }

    while (getline(file, line)) {
        // Convertimos la línea a minúsculas para que la búsqueda sea case-insensitive
        std::transform(line.begin(), line.end(), line.begin(), ::tolower);

        // Comprobamos si la línea contiene la palabra a buscar
        if (std::count(line.begin(), line.end(), word[0]) && std::search(line.begin(), line.end(), word.begin(), word.end(), [](unsigned char a, unsigned char b){return std::tolower(a) == std::tolower(b);})) {
            count++; // Incrementamos el contador si se encuentra la palabra
        }
    }

    // Cerramos el archivo
    file.close();

    // Mostramos el resultado
    std::cout << "La palabra '" << word << "' aparece " << count << " veces en el archivo." << std::endl;

    return 0;
}
